-- Profiles RLS policies
CREATE POLICY "用户可查看自己的资料" ON public.profiles
  FOR SELECT USING (auth.uid() = id);

CREATE POLICY "用户可更新自己的资料" ON public.profiles
  FOR UPDATE USING (auth.uid() = id);

-- Teams RLS policies
CREATE POLICY "团队成员可查看团队信息" ON public.teams
  FOR SELECT USING (
    EXISTS (
      SELECT 1 FROM public.team_members 
      WHERE team_id = id AND user_id = auth.uid()
    ) OR owner_id = auth.uid()
  );

CREATE POLICY "团队所有者和管理员可更新团队" ON public.teams
  FOR UPDATE USING (
    owner_id = auth.uid() OR 
    EXISTS (
      SELECT 1 FROM public.team_members 
      WHERE team_id = id AND user_id = auth.uid() AND role IN ('owner', 'admin')
    )
  );

CREATE POLICY "用户可创建团队" ON public.teams
  FOR INSERT WITH CHECK (owner_id = auth.uid());

-- Team members RLS policies
CREATE POLICY "团队成员可查看成员列表" ON public.team_members
  FOR SELECT USING (
    EXISTS (
      SELECT 1 FROM public.team_members tm 
      WHERE tm.team_id = team_id AND tm.user_id = auth.uid()
    ) OR 
    EXISTS (
      SELECT 1 FROM public.teams t 
      WHERE t.id = team_id AND t.owner_id = auth.uid()
    )
  );

CREATE POLICY "团队所有者和管理员可管理成员" ON public.team_members
  FOR ALL USING (
    EXISTS (
      SELECT 1 FROM public.team_members tm 
      WHERE tm.team_id = team_id AND tm.user_id = auth.uid() AND tm.role IN ('owner', 'admin')
    ) OR 
    EXISTS (
      SELECT 1 FROM public.teams t 
      WHERE t.id = team_id AND t.owner_id = auth.uid()
    )
  );

-- Extraction history RLS policies
